contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We may need to accept Ether to forward to c.wager()
    receive() external payable {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        // Preconditions: we will attempt to wager 'amount' on c. Ensure we hold enough ETH to forward.
        require(address(this).balance >= amount);

        // Read current observable bet limit and whether contract is open to public.
        uint256 beforeBetLimit = c.currentBetLimit(); if (__ESBMC_reverted()) return;
        // We don't have a direct getter for openToPublic, so we try to call wager only when bet limit equals amount.

        // Ensure caller had no prior wager according to public view
        bool hadWagerBefore = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return;

        // Record contract balance before the attempted wager
        uint256 beforeBalance = address(c).balance;

        // Attempt to place wager of 'amount' (must equal currentBetLimit for success). Capture revert.
        bool reverted;
        c.wager{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // After the call, either it reverted OR (if it succeeded) then:
        //  - hasPlayerWagered(address(this)) must be true
        //  - contract balance must have increased by exactly amount
        bool hasWagerAfter = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return;
        uint256 afterBalance = address(c).balance;

        // General property asserting the above relation. We also allow the trivial case that the call was disallowed
        // because preconditions like openToPublic or betLimit mismatch or onlyRealPeople or others caused revert.
        assert(
            reverted
            || (
                // If it didn't revert, it must have created a wager for this address
                hasWagerAfter
                // and contract balance must reflect the forwarded funds
                && afterBalance == beforeBalance + amount
                // and amount must have matched the observed bet limit (wager requires msg.value == betLimit)
                && amount == beforeBetLimit
                // and caller must not have been marked as having wagered before the call
                && hadWagerBefore == false
            )
        );
    }
}

