pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint256 beforeBetLimit;
        try c.currentBetLimit() returns (uint256 __r) { beforeBetLimit = __r; } catch { return; }
        bool hadWagerBefore;
        try c.hasPlayerWagered(address(this)) returns (bool __r) { hadWagerBefore = __r; } catch { return; }
        uint256 beforeBalance = address(c).balance;
        bool reverted;
        try c.wager{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        bool hasWagerAfter;
        try c.hasPlayerWagered(address(this)) returns (bool __r) { hasWagerAfter = __r; } catch { return; }
        uint256 afterBalance = address(c).balance;
        assertTrue(reverted
            || (
                // If it didn't revert, it must have created a wager for this address
                hasWagerAfter
                // and contract balance must reflect the forwarded funds
                && afterBalance == beforeBalance + amount
                // and amount must have matched the observed bet limit (wager requires msg.value == betLimit)
                && amount == beforeBetLimit
                // and caller must not have been marked as having wagered before the call
                && hadWagerBefore == false
            ));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
